// Map the Gmail message to the accounting receipt contract.
// NOTE: with simple:false the field names depend on your Gmail node version —
// verify each value below resolves (especially body_text). Adjust as needed.
const m = $json;
const id = String(m.id || m.messageId || m.threadId || '');
const from = m.From || m.from || (m.headers && m.headers.from) || '';
const subject = m.Subject || m.subject || (m.headers && m.headers.subject) || '';
const date = m.date || m.Date || (m.headers && m.headers.date) || new Date().toISOString();
const body_text = m.text || m.textPlain || m.snippet || '';
const body_html = m.textHtml || m.html || '';
const safeFrom = String(from).replace(/[^A-Za-z0-9]+/g, '_').slice(0, 40);
if (!id) { throw new Error('No Gmail message id — cannot build receipt'); }
return {
  json: {
    receipt: {
      id,
      filename: String(date).slice(0, 10) + '_' + safeFrom + '_' + id,
      date: String(date),
      from: String(from),
      subject: String(subject),
      body_text: String(body_text),
      body_html: String(body_html)
    }
  },
  binary: $binary
};
